-- ============================================================
-- 20261111000000_directory_listings.sql
-- DIRECTORY-01: public wedding vendor directory (venues first).
--
-- Anon surface #12 (read-only, definer RPCs - same posture as
-- get_invoice_by_token / get_inquiry_branding). No anon SELECT on the
-- table: RLS is on with zero policies, so the RPCs are the only path.
-- Only rows with published = true are ever returned.
--
-- Seed is facts only (name / city / state / type). No Google Places
-- data, no photos, no copied descriptions. Every row starts
-- verified = false. published = true only for rows that have a city
-- and no review flag; the rest stay hidden until checked.
-- Re-runnable: create-if-not-exists, create-or-replace, conflict-skip.
-- ============================================================

create table if not exists public.directory_listings (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  category text not null default 'venue',
  city text,
  state text not null check (char_length(state) = 2),
  venue_type text,
  website text,
  lat double precision,
  lng double precision,
  source_note text,
  review_flags text,
  verified boolean not null default false,
  published boolean not null default false,
  claimed_account_id uuid references public.accounts(id) on delete set null,
  claimed_at timestamptz,
  created_at timestamptz not null default now()
);

alter table public.directory_listings
  add column if not exists published boolean not null default false;

create index if not exists directory_listings_state_cat_idx
  on public.directory_listings (state, category)
  where published;

alter table public.directory_listings enable row level security;

-- Couples copy a listing into their own account-scoped vendors rolodex.
alter table public.vendors
  add column if not exists listing_id uuid
    references public.directory_listings (id) on delete set null;

create index if not exists vendors_listing_idx
  on public.vendors (account_id, listing_id)
  where listing_id is not null;

-- ---------- public read RPCs ----------
create or replace function public.directory_state_counts()
returns table (state text, listing_count bigint)
language sql stable security definer set search_path = public as $$
  select l.state, count(*)::bigint
  from public.directory_listings l
  where l.published
  group by l.state
$$;

create or replace function public.directory_listings_by_state(
  p_state text,
  p_category text default 'venue'
)
returns table (
  id uuid, slug text, name text, category text, city text, state text,
  venue_type text, website text, verified boolean, claimed boolean
)
language sql stable security definer set search_path = public as $$
  select l.id, l.slug, l.name, l.category, l.city, l.state,
         l.venue_type, l.website, l.verified,
         (l.claimed_account_id is not null)
  from public.directory_listings l
  where l.published
    and l.state = upper(p_state)
    and l.category = p_category
  order by l.city nulls last, l.name
$$;

create or replace function public.directory_listing_by_slug(p_slug text)
returns table (
  id uuid, slug text, name text, category text, city text, state text,
  venue_type text, website text, verified boolean, claimed boolean
)
language sql stable security definer set search_path = public as $$
  select l.id, l.slug, l.name, l.category, l.city, l.state,
         l.venue_type, l.website, l.verified,
         (l.claimed_account_id is not null)
  from public.directory_listings l
  where l.published and l.slug = p_slug
  limit 1
$$;

create or replace function public.directory_published_slugs()
returns table (slug text, state text)
language sql stable security definer set search_path = public as $$
  select l.slug, l.state from public.directory_listings l where l.published
$$;

revoke all on function public.directory_state_counts() from public;
revoke all on function public.directory_listings_by_state(text, text) from public;
revoke all on function public.directory_listing_by_slug(text) from public;
revoke all on function public.directory_published_slugs() from public;
grant execute on function public.directory_state_counts() to anon, authenticated;
grant execute on function public.directory_listings_by_state(text, text) to anon, authenticated;
grant execute on function public.directory_listing_by_slug(text) to anon, authenticated;
grant execute on function public.directory_published_slugs() to anon, authenticated;

-- ---------- starter seed (venues) ----------
on conflict (slug) do nothing;
